def make(i, row):
    tag, prompt, opts, answer, reason = row
    target_letters=['A','B','C','D','B','C','D','A','C','B']
    aid=target_letters[i-1]
    distractors=[t for t in opts if t != answer]
    ordered=[]; di=0
    for letter in ['A','B','C','D']:
        if letter == aid: ordered.append(answer)
        else: ordered.append(distractors[di]); di += 1
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(ordered)]
    steps = [f'讀題定位：圈出「{tag}」以及葡萄糖、氧氣、ATP、二氧化碳、熱、時間或代謝途徑。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合細胞代謝與能量轉換原理。', '排除誘答：分清有氧與無氧、反應物與產物、ATP媒介與熱散失，不把單一觀測過度延伸。', '最後回查：確認氧氣、溫度、細胞量、時間與重複測量條件都和題幹一致。']
    return {'id': f'question-science-content-bc-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-bc'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究細胞呼吸、ATP、有氧與無氧代謝、酵母實驗、熱散失與資料判讀的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-bc', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '生物體內的能量與代謝', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先辨識代謝途徑與反應物產物，再追蹤 ATP、熱與氣體資料，最後用控制變因與時間序列檢查呼吸速率。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-science-content-bc-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
